<template>
 <div class="container-fluid">
  <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h4 class="mb-1">Barcode labels</h4><div class="text-muted small">Select medicines, set label quantity and print adhesive labels.</div></div><button class="btn btn-primary" :disabled="!selected.length" @click="printLabels"><i class="bi bi-printer me-1"></i>Print {{ totalLabels }} labels</button></div>
  <div class="card mb-3"><div class="card-body row g-2"><div class="col-md-6"><input v-model="search" class="form-control" placeholder="Search medicine / barcode"></div><div class="col-md-3"><select v-model.number="perPage" class="form-select"><option :value="25">25 rows</option><option :value="50">50 rows</option><option :value="100">100 rows</option></select></div><div class="col-md-3 text-md-end"><button class="btn btn-outline-secondary" @click="load">Refresh</button></div></div></div>
  <div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th></th><th>Medicine</th><th>Barcode</th><th>Pack</th><th>Labels</th></tr></thead><tbody><tr v-for="m in medicines" :key="m.id"><td><input type="checkbox" class="form-check-input" :checked="!!selectedMap[m.id]" @change="toggle(m,$event.target.checked)"></td><td><b>{{m.name}}</b><div class="small text-muted">{{m.strength}} · {{m.generic_name}}</div></td><td>{{m.barcode || 'No barcode'}}</td><td>{{m.pack_size || 1}} {{m.unit}}</td><td><input type="number" min="1" max="200" class="form-control form-control-sm" style="width:90px" :value="selectedMap[m.id]?.qty || 1" :disabled="!selectedMap[m.id]" @change="setQty(m.id,$event.target.value)"></td></tr><tr v-if="!medicines.length"><td colspan="5" class="text-center text-muted py-4">No medicines found.</td></tr></tbody></table></div><div class="card-footer small text-muted">Labels use Code 128. A barcode value must be assigned to the medicine before printing.</div></div>
  <div class="print-area d-none"><div v-for="label in printable" :key="label.key" class="label"><div class="label-name">{{label.medicine.name}} {{label.medicine.strength}}</div><svg :id="'barcode-'+label.key"></svg><div class="label-code">{{label.medicine.barcode}}</div><div class="label-price">{{money(label.medicine.sale_price)}}</div></div></div>
 </div>
</template>
<script setup>
import {computed,onMounted,ref,watch,nextTick} from 'vue';import JsBarcode from 'jsbarcode';import api from '../api';import {money} from '../utils/format';
const medicines=ref([]),search=ref(''),perPage=ref(50),selected=ref([]);const selectedMap=computed(()=>Object.fromEntries(selected.value.map(x=>[x.id,x])));const totalLabels=computed(()=>selected.value.reduce((n,x)=>n+x.qty,0));const printable=computed(()=>selected.value.flatMap(x=>Array.from({length:x.qty},(_,i)=>({key:`${x.id}-${i}`,medicine:x.medicine}))));
async function load(){const {data}=await api.get('/medicines',{params:{search:search.value||undefined,per_page:perPage.value}});medicines.value=data.data||[];}function toggle(m,on){selected.value=on?[...selected.value,{id:m.id,medicine:m,qty:1}]:selected.value.filter(x=>x.id!==m.id);}function setQty(id,v){const n=Math.max(1,Math.min(200,Number(v)||1));selected.value=selected.value.map(x=>x.id===id?{...x,qty:n}:x);}async function printLabels(){const noBarcode=selected.value.filter(x=>!x.medicine.barcode);if(noBarcode.length){alert('Assign barcodes to selected medicines before printing.');return;}await nextTick();printable.value.forEach(x=>JsBarcode(`#barcode-${x.key}`,x.medicine.barcode,{format:'CODE128',displayValue:false,height:34,margin:2}));document.querySelector('.print-area').classList.remove('d-none');window.print();document.querySelector('.print-area').classList.add('d-none');}
watch([search,perPage],()=>load());onMounted(load);
</script>
<style>
@media print{body *{visibility:hidden!important}.print-area,.print-area *{visibility:visible!important}.print-area{display:grid!important;position:absolute;inset:0;grid-template-columns:repeat(3,1fr);gap:3mm;padding:3mm}.label{height:25mm;border:1px dashed #aaa;padding:2mm;text-align:center;break-inside:avoid;overflow:hidden}.label-name{font-size:9pt;font-weight:700;white-space:nowrap;overflow:hidden}.label svg{width:100%;height:11mm}.label-code{font-size:7pt;letter-spacing:1px}.label-price{font-size:8pt;font-weight:700}}
</style>
